<?php
namespace App\Services;
use App\Models\Product;
use Illuminate\Support\Facades\{DB,Cache,Log};
/** The Product model delegates here so single, bulk and other ORM deletes share one transaction. */
class ProductDeletion {
 private static function withoutProduct($value,$id){if(!is_array($value))return $value;if(isset($value['product_id'])&&(int)$value['product_id']===$id)return null;$list=array_values($value)===$value;foreach($value as $key=>$child){if($key==='product_ids'&&is_array($child))$value[$key]=array_values(array_filter($child,fn($x)=>(int)$x!==$id));elseif(is_array($child)){$after=self::withoutProduct($child,$id);if($after===null)unset($value[$key]);else $value[$key]=$after;}}return $list?array_values($value):$value;}
 public static function delete(Product $product,callable $remove){
  return DB::transaction(function()use($product,$remove){
   $p=Product::whereKey($product->getKey())->lockForUpdate()->first();if(!$p)return false;$id=(int)$p->id;$media=[];$paths=[];
   $collect=function($value)use(&$media,&$paths){$parts=json_decode((string)$value,true);if(!is_array($parts))$parts=explode(',',(string)$value);foreach($parts as $v){$v=trim($v);if(ctype_digit($v)&&(int)$v>0)$media[]=(int)$v;else{$path=ProductMediaCleanup::relative($v);if($path)$paths[]=$path;}}};
   foreach(['photos','thumbnail_img','meta_img','pdf','file_name','file_path']as $field)$collect($p->$field);
   $stocks=DB::table('product_stocks')->where('product_id',$id)->get(['id','image']);foreach($stocks as $stock)$collect($stock->image);
   foreach(['description','shortdescription']as $field){preg_match_all('~(?:src|href)\s*=\s*[\x22\x27]([^\x22\x27]+)~i',(string)$p->$field,$found);foreach($found[1]as $url)$collect(html_entity_decode($url,ENT_QUOTES));}
   $history=DB::table('business_settings')->where('type','product_image_versions_v1_'.$id)->lockForUpdate()->get();foreach($history as $row){$v=json_decode($row->value,true);if(!is_array($v)||!isset($v['entries'])||!is_array($v['entries']))throw new \RuntimeException('Saved image history cannot be read. Product was retained.');$collect($v['original']??'');foreach($v['entries']as $key=>$entry)$collect(is_array($entry)?($entry['id']??$key):$entry);}
   $isLink=function($url)use($p,$id){$parts=parse_url(html_entity_decode((string)$url,ENT_QUOTES));if($parts===false)return false;if(isset($parts['host'])&&!in_array(strtolower($parts['host']),['footsteponline.com','www.footsteponline.com',strtolower((string)parse_url(config('app.url'),PHP_URL_HOST))],true))return false;$path=rtrim(rawurldecode($parts['path']??''),'/');return $path==='/product/'.$id||($p->slug&&$path==='/product/'.$p->slug);};
   $bannerRows=DB::table('business_settings')->where('type',HomepageBanners::KEY)->lockForUpdate()->get();foreach($bannerRows as $row){$data=json_decode($row->value,true);if(!is_array($data)||!isset($data['items'])||!is_array($data['items']))continue;$before=$data['items'];$data['items']=array_values(array_filter($before,function($item)use($isLink,$collect){if(!$isLink($item['href']??''))return true;$collect($item['image_id']??'');$collect($item['mobile_image_id']??'');return false;}));if($before!==$data['items'])DB::table('business_settings')->where('id',$row->id)->update(['value'=>json_encode($data),'updated_at'=>now()]);}
   $legacy=DB::table('business_settings')->whereIn('type',['home_slider_images','home_slider_links'])->lockForUpdate()->get()->keyBy('type');if(isset($legacy['home_slider_links'])){$links=json_decode($legacy['home_slider_links']->value,true);$images=isset($legacy['home_slider_images'])?json_decode($legacy['home_slider_images']->value,true):[];if(is_array($links)&&is_array($images)){$changed=false;foreach($links as $i=>$href)if($isLink($href)){$collect($images[$i]??'');unset($links[$i],$images[$i]);$changed=true;}if($changed){DB::table('business_settings')->where('type','home_slider_links')->update(['value'=>json_encode(array_values($links)),'updated_at'=>now()]);if(isset($legacy['home_slider_images']))DB::table('business_settings')->where('type','home_slider_images')->update(['value'=>json_encode(array_values($images)),'updated_at'=>now()]);}}}
   DB::table('order_details')->where('product_id',$id)->whereNull('product_name_snapshot')->update(['product_name_snapshot'=>(string)$p->name]);
   $dealIds=DB::table('flash_deal_products')->where('product_id',$id)->pluck('flash_deal_id')->all();
   if($stocks->count())DB::table('inbox_order_drafts')->where('product_id',$id)->orWhereIn('stock_id',$stocks->pluck('id')->all())->delete();
   foreach(['carts','wishlists','reviews','product_stocks','product_taxes','product_translations','flash_deal_products','storefront_analytics_views','inbox_products','inbox_order_drafts']as $table)if(DB::getSchemaBuilder()->hasTable($table))DB::table($table)->where('product_id',$id)->delete();
   foreach(array_unique($dealIds)as $dealId){$deal=DB::table('flash_deals')->where('id',$dealId)->lockForUpdate()->first();if($deal&&!DB::table('flash_deal_products')->where('flash_deal_id',$dealId)->exists()){$collect($deal->banner);DB::table('flash_deals')->where('id',$dealId)->delete();}}
   if(DB::getSchemaBuilder()->hasTable('website_chat_threads'))DB::table('website_chat_threads')->where('product_id',$id)->update(['product_id'=>null,'product_context'=>null]);
   foreach(DB::table('product_addons')->lockForUpdate()->get(['id','product_ids'])as $addon){$ids=json_decode($addon->product_ids?:'[]',true);if(is_array($ids)&&in_array($id,array_map('intval',$ids),true))DB::table('product_addons')->where('id',$addon->id)->update(['product_ids'=>json_encode(array_values(array_filter($ids,fn($x)=>(int)$x!==$id))),'updated_at'=>now()]);}
   if(DB::getSchemaBuilder()->hasTable('coupons'))foreach(DB::table('coupons')->where('type','product_base')->lockForUpdate()->get(['id','details'])as $coupon){$before=json_decode($coupon->details,true);if(!is_array($before))continue;$after=self::withoutProduct($before,$id);if($after!==$before)DB::table('coupons')->where('id',$coupon->id)->update(['details'=>json_encode($after??[]),'updated_at'=>now()]);}
   DB::table('business_settings')->where('type','product_image_versions_v1_'.$id)->delete();
   $sections=DB::table('business_settings')->where('type',HomepageSections::KEY)->lockForUpdate()->get();foreach($sections as $row){$v=json_decode($row->value,true);if(!is_array($v))continue;$changed=false;foreach($v as &$section){if(is_array($section)&&isset($section['product_ids'])&&is_array($section['product_ids'])){$before=$section['product_ids'];$section['product_ids']=array_values(array_filter($before,fn($x)=>(int)$x!==$id));$changed=$changed||$before!==$section['product_ids'];}}unset($section);if($changed)DB::table('business_settings')->where('id',$row->id)->update(['value'=>json_encode($v),'updated_at'=>now()]);}
   $uploads=DB::table('uploads')->whereIn('id',array_values(array_unique($media)))->get();foreach(array_unique($paths)as $path){foreach(DB::table('uploads')->where('file_name',$path)->get()as $u)$uploads->push($u);}
   $jobs=[];foreach($uploads->unique('id')as $u){$job=ProductMediaCleanup::enqueue((int)$u->id,$u->file_name);if($job)$jobs[]=$job;}
   foreach(array_unique($paths)as $path)if(!DB::table('uploads')->where('file_name',$path)->exists()){$job=ProductMediaCleanup::enqueue(null,$path);if($job)$jobs[]=$job;}
   if(!$remove())throw new \RuntimeException('Product deletion failed; related data was retained.');
   DB::table('business_settings')->where('type','mobile_catalog_revision')->update(['value'=>DB::raw('CAST(value AS UNSIGNED)+1'),'updated_at'=>now()]);
   DB::afterCommit(function()use($jobs,$p){foreach(['business_settings','featured_products','best_selling_products','products','products-category-'.$p->category_id,'todays_deal_products']as $key)Cache::forget($key);if($jobs)try{\App\Jobs\CleanupDeletedProductMedia::dispatch(array_values(array_unique($jobs)));}catch(\Throwable $e){Log::warning('Product media queued for scheduled retry.');}});
   return true;
  });
 }
}
